} *>&1 | Out-String -Width 1KB -Stream >> "$env:TEMP\UserOnce.log";

$scripts = @(
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Edge\SmartScreenEnabled" /ve /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Edge\SmartScreenPuaEnabled" /ve /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\AppHost" /v EnableWebContentEvaluation /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\AppHost" /v PreventOverride /t REG_DWORD /d 0 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce" /v "UnattendedSetup" /t REG_SZ /d "powershell.exe -WindowStyle \""Normal\"" -ExecutionPolicy \""Unrestricted\"" -NoProfile -File \""C:\Windows\Setup\Scripts\UserOnce.ps1\""" /f;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to modify the default user’’s registry hive. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\DefaultUser.log";

$scripts = @(
	{
		# --- Enable permanent automatic logon ---
		$Winlogon = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
		
		Set-ItemProperty -Path $Winlogon -Name 'AutoAdminLogon' -Value '1' -Type String -Force
		Set-ItemProperty -Path $Winlogon -Name 'DefaultUserName' -Value 'carlos' -Type String -Force
		Set-ItemProperty -Path $Winlogon -Name 'DefaultDomainName' -Value $env:COMPUTERNAME -Type String -Force
		Set-ItemProperty -Path $Winlogon -Name 'DefaultPassword' -Value 'malware' -Type String -Force
		
		# Remove the automatic logon limit
		Remove-ItemProperty -Path $Winlogon -Name 'AutoLogonCount' -ErrorAction SilentlyContinue
	};
	{
		# --- Software installs ---
		$TempDir = "$env:TEMP\UnattendedSetup";
		New-Item -ItemType Directory -Force -Path $TempDir | Out-Null;

		# Chrome (Enterprise MSI - reliable silent install)
		Write-Host "Downloading Chrome Enterprise MSI...";
		Invoke-WebRequest -Uri 'https://dl.google.com/dl/chrome/install/googlechromestandaloneenterprise64.msi' -OutFile "$TempDir\ChromeSetup.msi" -UseBasicParsing;
		Write-Host "Installing Chrome...";
		Start-Process msiexec.exe -ArgumentList "/i `"$TempDir\ChromeSetup.msi`" /qn /norestart" -Wait;

		# Adobe Reader
		Invoke-WebRequest -Uri 'https://ardownload2.adobe.com/pub/adobe/acrobat/win/AcrobatDC/2100720099/AcroRdrDCx642100720099_MUI.exe' -OutFile "$TempDir\AcroRdr.exe" -UseBasicParsing;
		Start-Process "$TempDir\AcroRdr.exe" -ArgumentList '/sAll /rs /rps /msi' -Wait;

		# 7-Zip
		Invoke-WebRequest -Uri 'https://www.7-zip.org/a/7z2408-x64.exe' -OutFile "$TempDir\7z.exe" -UseBasicParsing;
		Start-Process "$TempDir\7z.exe" -ArgumentList '/S' -Wait;

		# Python 3
		Invoke-WebRequest -Uri 'https://www.python.org/ftp/python/3.12.0/python-3.12.0-amd64.exe' -OutFile "$TempDir\python.exe" -UseBasicParsing;
		Start-Process "$TempDir\python.exe" -ArgumentList '/quiet InstallAllUsers=1 PrependPath=1 Include_test=0' -Wait;

		# .NET Framework 4.8
		Invoke-WebRequest -Uri 'https://go.microsoft.com/fwlink/?linkid=2088631' -OutFile "$TempDir\ndp48.exe" -UseBasicParsing;
		Start-Process "$TempDir\ndp48.exe" -ArgumentList '/q /norestart' -Wait;

		# .NET 8.0 runtimes
		Invoke-WebRequest -Uri 'https://aka.ms/dotnet/8.0/dotnet-runtime-win-x64.exe' -OutFile "$TempDir\net8x64.exe" -UseBasicParsing;
		Start-Process "$TempDir\net8x64.exe" -ArgumentList '/install /quiet /norestart' -Wait;
		Invoke-WebRequest -Uri 'https://aka.ms/dotnet/8.0/dotnet-runtime-win-x86.exe' -OutFile "$TempDir\net8x86.exe" -UseBasicParsing;
		Start-Process "$TempDir\net8x86.exe" -ArgumentList '/install /quiet /norestart' -Wait;
	};
	{
		# --- Office Installation via ODT ---
		$TempDir = "$env:TEMP\UnattendedSetup";
		$ODTUrl = 'https://download.microsoft.com/download/6c1eeb25-cf8b-41d9-8d0d-cc1dbc032140/officedeploymenttool_20228-20124.exe';
		$ODTPath = "$TempDir\odt.exe";
		$ODTDir = "$TempDir\ODT";

		# 1. Write configuration.xml with CDN fallback (XML-escaped!)
		$ConfigXml = @'
<Configuration>
  <Add OfficeClientEdition="64" Channel="Current" AllowCdnFallback="TRUE">
    <Product ID="O365ProPlusRetail">
      <Language ID="en-US" />
    </Product>
  </Add>
  <RemoveMSI />
  <Display Level="None" AcceptEULA="TRUE" />
</Configuration>
'@;
		$ConfigXml | Out-File -FilePath "$TempDir\configuration.xml" -Encoding UTF8 -Force;

		# 2. Download ODT
		Invoke-WebRequest -Uri $ODTUrl -OutFile $ODTPath -UseBasicParsing;

		# 3. Extract ODT
		Start-Process -FilePath $ODTPath -ArgumentList "/extract:$ODTDir /quiet" -Wait;

		# 4. Install Office
		Start-Process -FilePath "$ODTDir\setup.exe" -ArgumentList "/configure `"$TempDir\configuration.xml`"" -Wait;
	};
	{
		# --- Enable macros ---
		foreach ($Version in @('16.0','15.0')) {
			foreach ($App in @('Word','Excel')) {
				$RegPath = "HKCU:\Software\Microsoft\Office\$Version\$App\Security";
				if (Test-Path $RegPath) {
					New-ItemProperty -Path $RegPath -Name 'VBAWarnings' -Value 1 -PropertyType DWORD -Force;
				}
			}
		}
	};
	{
		# --- MAS activation ---
		Start-Sleep -Seconds 15;
		powershell.exe -Command "& ([scriptblock]::Create((irm https://get.activated.win))) /HWID /Ohook";
	};
	{
		# --- Cleanup ---
		Remove-Item -LiteralPath @(
		  'C:\Windows\Panther\unattend.xml';
		  'C:\Windows\Panther\unattend-original.xml';
		  'C:\Windows\Setup\Scripts\Wifi.xml';
		) -Force -ErrorAction 'SilentlyContinue' -Verbose;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to finalize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\FirstLogon.log";
